import{_ as o,o as t,c as r,a2 as s}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"热键(设置页面)","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/hotkeys-page.md","filePath":"zh-CN/user-guide/settings/hotkeys-page.md","lastUpdated":1785993908000}'),a={name:"zh-CN/user-guide/settings/hotkeys-page.md"};function l(n,e,c,d,i,g){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="热键-设置页面" tabindex="-1">热键(设置页面) <a class="header-anchor" href="#热键-设置页面" aria-label="Permalink to &quot;热键(设置页面)&quot;">​</a></h1><p>三个 Tab:<strong>全局</strong>、<strong>插件动作</strong>、<strong>进程黑名单</strong>。每个热键具体做什么见<a href="./../hotkeys.html">热键</a>页面——这一篇只讲设置界面本身。</p><h2 id="全局" tabindex="-1">全局 <a class="header-anchor" href="#全局" aria-label="Permalink to &quot;全局&quot;">​</a></h2><p><strong>全局快捷键</strong>分组:</p><ul><li><strong>显示/隐藏快速搜索</strong> —— 录制控件;既可以录制成裸修饰键(双击模式，默认 <code>Ctrl</code>)，也可以录制成完整组合键。旁边的<strong>全屏应用聚焦时仍然响应</strong> —— 复选框，默认关闭;打开后这个热键(以及快速跳转、内嵌搜索唤出)会退出下面<a href="#process-blacklist">进程黑名单</a>里说的那套全屏自动放行机制。</li><li><strong>快速跳转</strong> —— 默认 <code>Ctrl+G</code>。</li></ul><p><strong>功能键</strong>分组:</p><ul><li>下一项(<code>Ctrl+N</code>)、上一项(<code>Ctrl+P</code>)、跳转到结果的修饰键(默认 <code>Ctrl</code>，配合数字 1–9)、打开动作菜单(<code>Ctrl+O</code>)、从选中项补全(<code>Ctrl+Tab</code>)、QuickLook(<code>Alt+P</code>)、上/下一条关键字历史 (<code>Alt+Up</code> / <code>Alt+Down</code>)、删除当前关键字历史(<code>Ctrl+Delete</code>)、打开完整窗口(默认 <code>Ctrl+F</code>——直接打开完整窗口并带上当前搜索内容)、打开发送窗口(默认 <code>Ctrl+S</code>——打开发送文件/文本至 LocalSend 设备的窗口)。</li><li>这里的每个录制控件都能接受任意按键或组合——包括裸 <code>Tab</code> 这种键——录制下来的绑定会优先于该按键原本可能存在的任何硬编码含义。</li></ul><p><strong>快速导航</strong>分组:</p><ul><li><strong>在空白处双击左键</strong> —— 复选框，默认开启。</li><li><strong>在空白处点击中键</strong> —— 复选框，默认开启。</li></ul><h2 id="插件动作" tabindex="-1">插件动作 <a class="header-anchor" href="#插件动作" aria-label="Permalink to &quot;插件动作&quot;">​</a></h2><p>每个插件注册的动作都有一条(比如复制路径、以管理员身份运行)，按注册它们的插件分组，各自带独立的热键录制控件。改之前会一直沿用插件自己建议的默认值。</p><h2 id="process-blacklist" tabindex="-1">进程黑名单 <a class="header-anchor" href="#process-blacklist" aria-label="Permalink to &quot;进程黑名单 {#process-blacklist}&quot;">​</a></h2><p>添加可执行文件名(例如 <code>game.exe</code>)，当它处于前台时，会完全放行 Lertaro 的全局热键、按键拦截，以及快速导航的双击/中键鼠标触发。不区分大小写，<code>.exe</code> 后缀可省略。和<strong>索引</strong>里的排除规则一样支持单条添加/批量编辑:一个单条输入框配<strong>添加进程</strong>按钮，一个现有条目列表，以及一个批量文本框配 <strong>生成文本</strong> / <strong>应用文本</strong>按钮。</p><p>这正是解决全屏游戏或其他会独占键盘原始输入的应用与热键冲突的方法——见<a href="./../troubleshooting.html#全局热键没有反应">故障排查</a>。任何真正全屏的前台应用都会自动获得同样的效果，不需要在这里手动添加——除非<strong>全局</strong>分组里&quot;显示/隐藏快速搜索&quot;旁边的<strong>全屏应用聚焦时仍然响应</strong>被打开，那样会整体退出这套自动豁免。无论哪种情况，当前活动窗口如果是文件选择器，都会被豁免，快速导航依然可以正常使用。</p>',14)])])}const u=o(a,[["render",l]]);export{p as __pageData,u as default};
